// Fixed-point WCAG relative luminance.
//
// The 256-entry sRGB -> linear table in data/srgb-linear.json is generated by
// scripts/gen-srgb-linear.mjs and committed. It is the cross-language contract;
// do not replace it with a runtime float conversion.
import srgbTableJson from '../data/srgb-linear.json' with { type: 'json' };
import { LUMINANCE_MAX, LUMINANCE_WEIGHTS, LUMINANCE_WEIGHT_DENOMINATOR, RED_RATIO } from './constants.ts';

const [WEIGHT_R, WEIGHT_G, WEIGHT_B] = LUMINANCE_WEIGHTS;
const DENOMINATOR = LUMINANCE_WEIGHT_DENOMINATOR;
const RED_RATIO_NUMERATOR = Math.round(RED_RATIO * 1000);
const RED_RATIO_DENOMINATOR = 1000;

export const SRGB_TO_LINEAR: Uint16Array = Uint16Array.from(srgbTableJson as readonly number[]);

// Precompute nearest sRGB byte for every 16-bit linear value. Exact table
// entries are restored afterwards, so converting a byte to linear and back is
// the identity for every 8-bit input.
export const LINEAR_TO_SRGB: Uint8Array = (() => {
  const reverse = new Uint8Array(LUMINANCE_MAX + 1);
  let byte = 0;
  for (let linear = 0; linear <= LUMINANCE_MAX; linear++) {
    while (
      byte < 255 &&
      Math.abs((SRGB_TO_LINEAR[byte + 1] as number) - linear) <=
        Math.abs((SRGB_TO_LINEAR[byte] as number) - linear)
    ) {
      byte++;
    }
    reverse[linear] = byte;
  }
  for (let b = 0; b < 256; b++) {
    reverse[SRGB_TO_LINEAR[b] as number] = b;
  }
  return reverse;
})();

// Y = (13933 R + 46871 G + 4732 B) / 65536, all channels linear 0..65535.
// The weights sum to exactly 65536; floor division keeps the result an integer.
export function luminanceFromLinear(r: number, g: number, b: number): number {
  return Math.floor((WEIGHT_R * r + WEIGHT_G * g + WEIGHT_B * b) / DENOMINATOR);
}

export function luminanceFromSrgb(r: number, g: number, b: number): number {
  return luminanceFromLinear(
    SRGB_TO_LINEAR[r] as number,
    SRGB_TO_LINEAR[g] as number,
    SRGB_TO_LINEAR[b] as number,
  );
}

// A saturated red is R / (R + G + B) >= 0.8 on linear values. In integer form
// this is 5R >= 4(R + G + B) and R + G + B > 0.
export function isSaturatedRedLinear(r: number, g: number, b: number): boolean {
  const sum = r + g + b;
  return sum > 0 && r * RED_RATIO_DENOMINATOR >= sum * RED_RATIO_NUMERATOR;
}

export function isSaturatedRedSrgb(r: number, g: number, b: number): boolean {
  return isSaturatedRedLinear(
    SRGB_TO_LINEAR[r] as number,
    SRGB_TO_LINEAR[g] as number,
    SRGB_TO_LINEAR[b] as number,
  );
}
